const body = $json.body || $json;

const cliente = body.cliente || 'Cliente General';
const total = Number(body.total || 0).toLocaleString('es-CL');
const metodoPago = body.metodo_pago || 'No especificado';
const articulos = body.articulos || 1;
const usuario = body.usuario_nombre || 'Cajero';

const mensaje = `⚡ <b>¡NUEVA VENTA REGISTRADA!</b>\n\n` +
`👤 <b>Cliente:</b> ${cliente}\n` +
`💵 <b>Total:</b> $${total}\n` +
`💳 <b>Medio de Pago:</b> ${metodoPago}\n` +
`📦 <b>Artículos:</b> ${articulos}\n` +
`🧑‍💼 <b>Atendido por:</b> ${usuario}\n` +
`🕒 <i>${new Date().toLocaleTimeString('es-ES')}</i>`;

return [{ json: { mensaje } }];
